using Microsoft.CodeAnalysis.Testing;
using VerifyCS = CSharpSourceGeneratorVerifier<MessagePack.SourceGenerator.MessagePackGenerator>;

namespace Receipts.GeneratedTests;

public class SuppressSourceGenerationAnalyzerTests
{
    [Fact]
    public async Task SuppressedType_MissingKey_ReportsMsgPack004()
    {
        string testSource = """
            using MessagePack;

            [MessagePackObject(SuppressSourceGeneration = true)]
            public class MyObject
            {
                [Key(0)]
                public int A { get; set; }

                public int {|MsgPack004:B|} { get; set; }
            }
            """;
        var test = new VerifyCS.Test
        {
            TestState = { Sources = { testSource } },
            TestBehaviors = TestBehaviors.SkipGeneratedSourcesCheck,
        };
        await test.RunAsync();
    }

    [Fact]
    public async Task NotSuppressedType_MissingKey_ReportsMsgPack004()
    {
        string testSource = """
            using MessagePack;

            [MessagePackObject]
            public class MyObject
            {
                [Key(0)]
                public int A { get; set; }

                public int {|MsgPack004:B|} { get; set; }
            }
            """;
        var test = new VerifyCS.Test
        {
            TestState = { Sources = { testSource } },
            TestBehaviors = TestBehaviors.SkipGeneratedSourcesCheck,
        };
        await test.RunAsync();
    }
}
